local DIET_EN = WA.LR { meat = L"meat", fish = L"fish", bread = L"bread", cheese = L"cheese", fruit = L"fruit", fungus = L"fungus" }
P.DIET_EN = DIET_EN

local function Data() return WowAssistantPets end
function P.HasData() return Data() ~= nil end

-- Beasts as tables (cached): { npc, name, family, min, max, rare, elite, zone, speed, teaches = { [ability] = rank } }
local beasts
function P.Beasts()
  if beasts then return beasts end
  local D = Data()
  beasts = {}
  if not D then return beasts end
  for _, r in ipairs(D.beasts) do
    local b = { npc = r[1], name = r[2], family = r[3], min = r[4], max = r[5], rare = r[6]:find("R") ~= nil,
      elite = r[6]:find("E") ~= nil, zone = r[7], speed = r[8], teaches = {} }
    for name, rank in (r[9] or ""):gmatch("([^:]+):(%d+) ?") do b.teaches[name] = tonumber(rank) end
    beasts[#beasts + 1] = b
  end
  return beasts
end
function P.Reset() beasts = nil end

-- Attack speed in seconds, and how much faster than the normal 2.0.
function P.Speed(b) return (b.speed or 200) / 100 end
function P.SpeedLabel(b)
  local s = P.Speed(b)
  if s >= 2 - 1e-6 and s <= 2 + 1e-6 then return (L"2.0 s") end
  local pct = math.floor((2 / s - 1) * 100 + 0.5)
  return (L"%.1f s (%s%d%%)"):format(s, pct >= 0 and "+" or "", pct)
end

-- Relative pet DPS: family damage × attack speed (a 2.0 s, 1.00 damage beast is 1).
function P.DpsFactor(b)
  local f = P.FAMILY[b.family]
  return (f and f.dmg or 1) * 2 / P.Speed(b)
end
-- Relative toughness: armor × health.
function P.Toughness(b)
  local f = P.FAMILY[b.family]
  return f and (f.armor * f.hp) or 1
end

-- The best beasts to tame at this hunter level: { dps = {...}, tank = {...} }, each a list of
-- { beast, factor }. Beasts above your level cannot be tamed; ones far below level slowly.
function P.Best(level, n)
  n = n or 8
  local dps, tank = {}, {}
  for _, b in ipairs(P.Beasts()) do
    if b.min > 0 and b.min <= level then
      local near = b.min >= level - 12
      dps[#dps + 1] = { beast = b, factor = P.DpsFactor(b), near = near }
      tank[#tank + 1] = { beast = b, factor = P.Toughness(b) * (b.family == "Turtle" and 1.05 or 1), near = near }
    end
  end
  local function order(a, c)
    if a.near ~= c.near then return a.near end
    if math.abs(a.factor - c.factor) > 1e-6 then return a.factor > c.factor end
    if a.beast.elite ~= c.beast.elite then return not a.beast.elite end
    return a.beast.min > c.beast.min
  end
  table.sort(dps, order)
  table.sort(tank, order)
  -- one beast per family and speed: the list should show choices, not 8 identical cats
  local function trim(list)
    local out, seen = {}, {}
    for _, e in ipairs(list) do
      local key = e.beast.family .. "/" .. e.beast.speed
      if not seen[key] then seen[key] = true out[#out + 1] = e end
      if #out >= n then break end
    end
    return out
  end
  return { dps = trim(dps), tank = trim(tank) }
end

-- Families with what they can learn (from the beasts that teach it) and how many beasts there are.
local famInfo
function P.Families()
  if famInfo then return famInfo end
  famInfo = {}
  for _, b in ipairs(P.Beasts()) do
    local f = famInfo[b.family]
    if not f then f = { name = b.family, count = 0, abilities = {}, fastest = 200, minLevel = 99 } famInfo[b.family] = f end
    f.count = f.count + 1
    if b.min > 0 then f.minLevel = math.min(f.minLevel, b.min) end
    if b.speed < f.fastest then f.fastest = b.speed end
    for name, rank in pairs(b.teaches) do f.abilities[name] = math.max(f.abilities[name] or 0, rank) end
  end
  return famInfo
end

-- Ranks of an ability: { { rank, spell, level, tp, cost, cd, desc }, ... } in rank order.
function P.Ranks(name)
  local D = Data()
  local list = D and D.abilities[name] or {}
  local out = {}
  for _, r in ipairs(list) do
    out[#out + 1] = { rank = r[1], spell = r[2], level = r[3], tp = r[4], cost = r[5], cd = r[6], desc = r[7] }
  end
  table.sort(out, function(a, b) return a.rank < b.rank end)
  return out
end

-- Beasts that teach this rank, tameable at your level, best first (closest to your level).
function P.Teachers(ability, rank, level, n)
  local out = {}
  for _, b in ipairs(P.Beasts()) do
    if b.teaches[ability] == rank and b.min > 0 and b.min <= level then out[#out + 1] = b end
  end
  table.sort(out, function(a, b)
    if a.elite ~= b.elite then return not a.elite end
    return a.min > b.min
  end)
  while #out > (n or 3) do table.remove(out) end
  return out
end

-- Where a beast is: "Zone, 23-24. szint (ritka, elit)".
function P.Where(b)
  local lvl = b.min == b.max and tostring(b.min) or (b.min .. "–" .. b.max)
  local flags = {}
  if b.rare then flags[#flags + 1] = L"rare" end
  if b.elite then flags[#flags + 1] = L"elite" end
  return (L"%s, level %s%s"):format(b.zone, lvl, #flags > 0 and (" (" .. table.concat(flags, ", ") .. ")") or "")
end

-- What to teach the pet next. input = { level (hunter), pet = { family, level, tp, tpSpent, known = { [ability] = rank } }
-- or nil, taught = { [ability] = rank } (Beast Training) or nil }.
-- Returns rows { ability, have, rank, tp, petLevel, status, teachers, note, prio } best first,
-- and the training points left.
function P.Training(input)
  local pet = input.pet
  if not pet or not pet.family then return nil end
  local fam = P.Families()[pet.family]
  if not fam then return nil end
  local petLevel = pet.level or input.level or 1
  local known = pet.known or {}
  local taught = input.taught
  local left = (pet.tp or 0) - (pet.tpSpent or 0)
  local rows = {}
  for name in pairs(fam.abilities) do
    local info = P.ABILITY[name] or { hu = "", prio = 5 }
    local ranks = P.Ranks(name)
    local best, nextRank
    for _, r in ipairs(ranks) do
      if r.level <= petLevel then best = r elseif not nextRank then nextRank = r end
    end
    local have = known[name] or 0
    -- a new rank replaces the old one: its training points come back, so the cost is the difference
    local haveTp = 0
    for _, r in ipairs(ranks) do if r.rank == have then haveTp = r.tp end end
    local row = { ability = name, have = have, prio = info.prio, hu = info.hu, next = nextRank }
    if best and best.rank > have then
      row.rank, row.tp, row.petLevel = best.rank, math.max(0, best.tp - haveTp), best.level
      row.desc = best.desc
      if info.prio >= 9 then
        row.status = "skip"
      elseif taught and (taught[name] or 0) >= best.rank then
        row.status = "teach"
      else
        row.status = "tame"
        row.teachers = P.Teachers(name, best.rank, input.level or petLevel, 2)
        if #row.teachers == 0 then
          -- nobody at your level teaches it: the lowest beast that does, for later
          local later
          for _, b in ipairs(P.Beasts()) do
            if b.teaches[name] == best.rank and b.min > 0 and (not later or b.min < later.min) then later = b end
          end
          row.teachers, row.laterTeacher = {}, later
        end
      end
    elseif have > 0 or best then
      row.rank, row.status = have, "done"
      row.desc = best and best.desc
    else
      row.status = "later"
      row.rank = nextRank and nextRank.rank
      row.petLevel = nextRank and nextRank.level
    end
    rows[#rows + 1] = row
  end
  local ORDER = { teach = 1, tame = 2, done = 3, later = 4, skip = 5 }
  table.sort(rows, function(a, b)
    if ORDER[a.status] ~= ORDER[b.status] then return ORDER[a.status] < ORDER[b.status] end
    if a.prio ~= b.prio then return a.prio < b.prio end
    return a.ability < b.ability
  end)
  -- what the training points cover, in this order
  local budget = left
  for _, r in ipairs(rows) do
    if (r.status == "teach" or r.status == "tame") and r.tp then
      r.fits = budget >= r.tp
      if r.fits then budget = budget - r.tp end
    end
  end
  return { rows = rows, left = left, family = pet.family }
end

